<?php $price=(float)$p['sale_price']; ?><article class="product-card"><a class="product-image" href="<?=url('product.php?slug='.urlencode($p['slug']))?>"><?php if(!empty($p['image'])):?><img src="<?=url($p['image'])?>" alt="<?=h($p['name'])?>"><?php else:?><div class="placeholder"><span><?=h(mb_substr($p['name'],0,1))?></span><small>TOPLUCA</small></div><?php endif;?><?php if(!empty($p['compare_price'])&&(float)$p['compare_price']>$price):?><b class="badge">Fırsat</b><?php elseif((int)$p['sales_count']>50):?><b class="badge dark">Çok Satan</b><?php endif;?></a><div class="product-body"><div class="brand"><?=h($p['brand_name']??'')?></div><a class="name" href="<?=url('product.php?slug='.urlencode($p['slug']))?>"><?=h($p['name'])?></a><div class="rating">★★★★★</div><div class="price"><?php if(!empty($p['compare_price'])&&(float)$p['compare_price']>$price):?><del><?=money($p['compare_price'])?></del><?php endif;?><strong><?=money($price)?></strong></div><form method="post" action="<?=url('cart.php')?>"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="add-cart">Sepete Ekle</button></form><div class="delivery"><?php if($p['shipping_policy']==='free'):?>✓ Ücretsiz Kargo<?php elseif((int)$p['same_day_delivery']===1):?>⚡ Ankara Aynı Gün<?php else:?>🚚 Hızlı Gönderim<?php endif;?></div></div></article>
